-- Hosbah (MH-575 H5): real-user monitoring settings, one row per app. key_hash is the SHA-256 of
-- the public, non-secret ingest key (hbr_…, internal/tokens) that the beacon script (GET /rum.js,
-- served with data-key="…") posts back to POST /api/rum/{key}; the key itself is shown once, at
-- enable or rotation (like apps.deploy_hook_hash). It is "public" in the sense that it travels in
-- page source to every visitor's browser, not a secret — but it is still the only thing that lets
-- an ingest request resolve to a team, so it is looked up in system scope exactly like a heartbeat
-- ping token (monitors.ping_token_hash), then the rest of the ingest transaction re-points at that
-- app's team with tenancy.SetTeam. Disabled (enabled = false) drops every ingest for the app
-- without needing to know the key at all: the settings row is read before the key is even checked.
ALTER TABLE app_rum_settings ADD CONSTRAINT app_rum_settings_app_id_key UNIQUE (app_id);
CREATE UNIQUE INDEX app_rum_settings_key_hash_key ON app_rum_settings (key_hash) WHERE key_hash IS NOT NULL;
CREATE INDEX app_rum_settings_team_idx ON app_rum_settings (team_id);
